let status = msg.status;
if (status.text.includes('connected')) {
    msg.payload = true; // Connected
} else {
    msg.payload = false; // Disconnected or other state
}
// Store status for SVG maybe?
flow.set("mqtt_connected", msg.payload);
return msg;

// Basic validation (expand as needed)
if (msg.payload && 
    typeof msg.payload.temperature_c === 'number' && 
    typeof msg.payload.vibration_rms === 'number' &&
    typeof msg.payload.pressure_bar === 'number' &&
    typeof msg.payload.power_kw === 'number') {

    // Add timestamp
    const now = new Date();
    msg.payload.timestamp = now.toISOString();

    // Store the validated payload for other branches & manual trigger
    context.set("lastValidData", msg.payload);

    // Prepare outputs for different paths
    const dataForPrediction = JSON.stringify(msg.payload);
    const tempData = { payload: msg.payload.temperature_c };
    const vibData = { payload: msg.payload.vibration_rms };
    const pressData = { payload: msg.payload.pressure_bar };
    const powerData = { payload: msg.payload.power_kw };
    const statusCheckData = { payload: msg.payload }; // Pass full payload for status checks
    const svgDataInput = { payload: msg.payload }; // Pass for SVG data prep
    const lastTimeData = { payload: now }; // Just the timestamp

    // Output: 
    // 1: Prediction Path (Stringified JSON)
    // 2: Temperature Path
    // 3: Vibration Path
    // 4: Pressure Path
    // 5: Power Path
    // 6: Status Check Switches Path
    // 7: SVG Data Preparation Path
    // 8: Last Data Timestamp Path

    return [ 
        { payload: dataForPrediction }, 
        tempData,
        vibData,
        pressData,
        powerData,
        statusCheckData, 
        svgDataInput,
        lastTimeData
    ];

} else {
    node.warn("Received invalid MQTT payload structure: " + JSON.stringify(msg.payload));
    context.set("lastValidData", null); // Clear last data on invalid input
    return null; // Stop flow for invalid data
}

msg.payload = {
    level: "warn",
    message: "Prediction script wrote to stderr",
    stderr: msg.payload,
    source: "predict_fault.py"
}
return msg;

// msg.payload contains the return code
if (msg.payload !== 0) {
    const errorMsg = {
        payload: {
            level: "error",
            message: "Prediction script exited with non-zero code: " + msg.payload,
            return_code: msg.payload,
            source: "predict_fault.py"
        }
    };
    node.send(errorMsg);
    return;
}
return null;

const threshold = 85;
// Pass through original value
const original_msg = { payload: msg.payload }; 
// Create message for threshold line
const threshold_msg = { 
    payload: threshold, 
    topic: "Threshold" // Assign a topic for the series
};

// Return both messages to plot both lines
return [ original_msg, threshold_msg ];

let prediction = msg.payload.prediction || "N/A";
// Attempt to format confidence, handle potential errors
let confidence = "N/A";
try {
    if (msg.payload.confidence !== undefined && msg.payload.confidence !== null) {
        confidence = (parseFloat(msg.payload.confidence) * 100).toFixed(1) + "%";
    }
} catch (e) {
    node.warn("Could not format confidence: " + msg.payload.confidence);
}

let color = "grey"; // Default to grey if N/A
let text = `Prediction: ${prediction} (${confidence})`;

if (prediction === "Normal") {
    color = "green";
} else if (prediction !== "N/A") {
    color = "red"; // Non-normal and not N/A is red
}

msg.payload = text;
msg.color = color;

return msg;

const MAX_LOG_SIZE = 20;

// Get current states from context, default to normal/false
let states = context.get("systemStates") || {
    temp: 'ok', // ok, high
    vib: 'ok', // ok, high
    pred: 'ok', // ok, fault
    acknowledged: false // New state
};

let alertLog = context.get("alertLog") || [];
let newAlert = null;
let triggerTableUpdate = false;

// Check for Acknowledge signal
if (msg.topic === 'ACK_ALERT') {
    states.acknowledged = true;
    // Option 1: Reset source states on Ack
    // states.temp = 'ok';
    // states.vib = 'ok';
    // states.pred = 'ok'; 
    // Option 2: Just mark as acknowledged, status changes only when underlying condition clears.
    // Let's use Option 2 for clearer state representation
    node.log("Alerts acknowledged.");
} 
// Update state based on incoming alert topic (only if not acknowledged recently)
else if (msg.topic === 'ALERT_TEMP') {
    if(states.temp !== 'high') {
        newAlert = msg.alert;
        states.acknowledged = false; // New alert overrides ack
    }
    states.temp = 'high';
} else if (msg.topic === 'ALERT_VIB') {
     if(states.vib !== 'high') {
        newAlert = msg.alert;
        states.acknowledged = false;
    }
    states.vib = 'high';
} else if (msg.topic === 'ALERT_PRED') {
     if(states.pred !== 'fault') {
        newAlert = msg.alert;
        states.acknowledged = false;
    }
    states.pred = 'fault';
} 
// Handle reset conditions from normal path inputs
else if (msg.payload && typeof msg.payload === 'object') { 
    if (msg.payload.temperature_c <= 85) states.temp = 'ok';
    if (msg.payload.vibration_rms <= 2.5) states.vib = 'ok';
    if (msg.payload.prediction === 'Normal') states.pred = 'ok';

    // If all conditions clear, clear acknowledged flag too
    if(states.temp === 'ok' && states.vib === 'ok' && states.pred === 'ok') {
        states.acknowledged = false;
    }
}

// --- Determine Overall Status --- 
let overallStatus = {
    text: "Normal",
    color: "green",
    icon: "fa fa-check-circle",
    led: true
};
let isAlertActive = false;

if (states.pred === 'fault') {
    isAlertActive = true;
    overallStatus = {
        text: states.acknowledged ? "Fault Predicted (Ack)" : "Alert: Fault Predicted",
        color: states.acknowledged ? "grey" : "red",
        icon: states.acknowledged ? "fa fa-check" : "fa fa-exclamation-circle",
        led: !states.acknowledged // LED true(green) if ack'd, false(red) if active
    };
} else if (states.temp === 'high' || states.vib === 'high') {
    isAlertActive = true;
    overallStatus = {
        text: states.acknowledged ? "High Sensor (Ack)" : "Warning: High Sensor",
        color: states.acknowledged ? "grey" : "orange",
        icon: states.acknowledged ? "fa fa-check" : "fa fa-exclamation-triangle",
        led: !states.acknowledged // LED true(green) if ack'd, false(yellow/orange) if active
    };
}

// --- Update Alert Log --- 
if (newAlert) {
    newAlert.timestamp = new Date().toISOString();
    alertLog.unshift(newAlert); // Add to beginning
    if (alertLog.length > MAX_LOG_SIZE) {
        alertLog.pop(); // Remove oldest
    }
    triggerTableUpdate = true; // Signal to update table
}

// --- Prepare Outputs --- 
// Pass through the consolidated state for SVG use
msg.systemStates = states; 
msg.payload = {}; // Clear original payload
msg.payload.overall_status = overallStatus;
msg.payload.temp_led = (states.temp === 'ok');
msg.payload.vib_led = (states.vib === 'ok');
msg.payload.pred_led = (states.pred === 'ok');
msg.payload.triggerTableUpdate = triggerTableUpdate;
msg.payload.ackButtonDisabled = !isAlertActive || states.acknowledged; // Disable Ack button if no active alert or already ack'd

// Store updated states and log
context.set("systemStates", states);
context.set("alertLog", alertLog);

return msg;

