let alertLog = context.get("alertLog") || [];

// Format for ui_table
msg.payload = alertLog.map(alert => {
    return {
        "Timestamp": new Date(alert.timestamp).toLocaleString(),
        "Type": alert.type,
        "Message": alert.message
    }
});

return msg;

// Get latest sensor data (from input) and system states (from context/input)
const sensorData = msg.payload || {}; // Input should be the raw sensor payload
const systemStates = msg.systemStates || context.get("systemStates") || {}; // Get states from status function output

const temp = sensorData.temperature_c;
const vib = sensorData.vibration_rms;
const status = systemStates.acknowledged ? 'acknowledged' : 
               (systemStates.pred === 'fault' ? 'fault' : 
               (systemStates.temp === 'high' || systemStates.vib === 'high' ? 'warning' : 'normal'));

const tempThresholdHigh = 85;
const tempThresholdWarn = 75;
const vibThresholdHigh = 2.5;
const vibThresholdWarn = 2.0;

let svgStyles = {
    motorStyle: { fill: '#0056b3' }, // default blue
    pumpHeadLeftStyle: { fill: '#868e96' }, // default grey
    pumpHeadRightStyle: { fill: '#868e96' }, // default grey
    statusIndicatorStyle: { fill: 'grey' }, // default grey
    vibrationIndicatorStyle: { fill: 'none', stroke: 'none' } // default hidden
};

// Apply status color first
if (status === 'normal') {
    svgStyles.statusIndicatorStyle.fill = 'green';
    // Base colors for normal state
    svgStyles.motorStyle.fill = '#0056b3';
    svgStyles.pumpHeadLeftStyle.fill = '#868e96';
    svgStyles.pumpHeadRightStyle.fill = '#868e96';
} else if (status === 'warning') {
    svgStyles.statusIndicatorStyle.fill = 'orange';
    svgStyles.motorStyle.fill = 'orange'; // Example: motor turns orange on warning
} else if (status === 'fault') {
    svgStyles.statusIndicatorStyle.fill = 'red';
    svgStyles.motorStyle.fill = 'darkred'; // Example: motor turns dark red on fault
    svgStyles.pumpHeadLeftStyle.fill = 'darkred';
    svgStyles.pumpHeadRightStyle.fill = 'darkred';
} else if (status === 'acknowledged') {
     svgStyles.statusIndicatorStyle.fill = 'grey'; // Indicate acknowledged
     // Keep component colors based on underlying state?
     if(systemStates.temp === 'high' || systemStates.vib === 'high') {
         svgStyles.motorStyle.fill = 'darkgrey'; // Muted warning color
     } 
     if (systemStates.pred === 'fault') {
         svgStyles.motorStyle.fill = '#500000'; // Muted fault color
         svgStyles.pumpHeadLeftStyle.fill = '#500000';
        svgStyles.pumpHeadRightStyle.fill = '#500000';
     }
}

// Override/adjust colors based on specific sensor values
if (temp >= tempThresholdHigh) {
    // Make heads red, even if status isn't fault (e.g., just temp high)
    if(status !== 'fault' && status !== 'acknowledged') { // Avoid overriding fault/ack color
       svgStyles.pumpHeadLeftStyle.fill = 'red';
       svgStyles.pumpHeadRightStyle.fill = 'red';
    } 
} else if (temp >= tempThresholdWarn) {
     if(status !== 'fault' && status !== 'acknowledged') {
        svgStyles.pumpHeadLeftStyle.fill = 'orange';
        svgStyles.pumpHeadRightStyle.fill = 'orange';
     }
}

// Set vibration indicator color
if (vib >= vibThresholdHigh) {
    svgStyles.vibrationIndicatorStyle = { fill: 'red', stroke: 'red' };
} else if (vib >= vibThresholdWarn) {
    svgStyles.vibrationIndicatorStyle = { fill: 'orange', stroke: 'orange' };
}

msg.payload = svgStyles;
return msg;

// If lastValidData exists, format it like output 1 of the distributor
if (msg.payload) {
    msg.payload = JSON.stringify(msg.payload);
    return msg;
}
node.warn("No valid data available for manual prediction.");
return null;

