let rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) {
    node.warn("No data fetched from MySQL");
    return null;
}

let csvContent = "time_min,motor_rpm,pressure_bar,temperature_c,vibration_rms,power_kw,airflow_demand_cfm,torque_nm,noise_db,oilpump_power_w,motor_health,compressor_health,tank_health,blockage_factor,leak_rate_lpm,load_unload_cycles,repair_status,pressure_change_rate,temperature_change_rate,vibration_moving_avg,time_since_last_repair\n";
