// تحضير الرسالة باللغتين الإنجليزية والروسية
msg.topic = "Email from Node-RED"; // الموضوع

// محتوى الرسالة
msg.payload = "[ALERT] Compressor fault detected\n" +
              "Status: Overheating\n" +
              "Time: 2025-04-15 15:42:02\n" +
              "Predicted RUL: 2.0 hours\n\n" +
              "[ПРЕДУПРЕЖДЕНИЕ] Обнаружена неисправность компрессора\n" +
              "Состояние: Перегрев\n" +
              "Время: 2025-04-15 15:42:02\n" +
              "Предсказанный RUL: 2.0 часов";

return msg;

let data = msg.payload;
if (typeof data === "string") {
    try { data = JSON.parse(data); }
    catch (err) { node.warn("Invalid sensor JSON: " + err.message); return null; }
}
if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.warn("Sensor payload must be a JSON object.");
    return null;
}
const required = ["pressure_bar", "temperature_c", "vibration_rms", "power_kw"];
if (required.some((key) => data[key] === undefined || data[key] === null || !Number.isFinite(Number(data[key])))) {
    node.warn("Sensor payload is missing a required numeric measurement.");
    return null;
}
const allowed = [
    "time_min", "motor_rpm", "pressure_bar", "temperature_c", "vibration_rms",
    "power_kw", "airflow_demand_cfm", "torque_nm", "noise_db", "oilpump_power_w",
    "motor_health", "compressor_health", "tank_health", "blockage_factor", "leak_rate_lpm",
    "load_unload_cycles", "repair_status", "pressure_change_rate", "temperature_change_rate",
    "vibration_moving_avg", "time_since_last_repair"
];
const columns = [];
const values = [];
for (const key of allowed) {
    if (data[key] === undefined || data[key] === null) continue;
    const value = Number(data[key]);
    if (!Number.isFinite(value)) continue;
    columns.push(key);
    values.push(value);
}
if (!columns.includes("time_min")) {
    columns.unshift("time_min");
    values.unshift(Date.now() / 60000);
}
columns.push("timestamp");
values.push(new Date());
msg.topic = `INSERT INTO compressor_data (${columns.map((key) => `\`${key}\``).join(", ")}) VALUES (${columns.map(() => "?").join(", ")})`;
msg.payload = values;
return msg;

const result = msg.payload;
if (!result || result.error || !Number.isFinite(Number(result.ttf_class))) {
    node.warn("RUL prediction result is missing a numeric ttf_class.");
    return null;
}
const prediction = Number(result.ttf_class);
msg.topic = "INSERT INTO rul_predictions (prediction_time, RUL_value, prediction_meta) VALUES (?, ?, ?)";
msg.payload = [new Date(), prediction, JSON.stringify(result)];
return msg;
